window.YUGEN_ATLAS={"entries": [{"id": "jomon", "category": "historia", "title": "Jōmon: marcas no barro", "kana": "縄文", "tag": "PRÉ-HISTÓRIA", "lead": "Antes dos castelos, havia comunidades, redes e cerâmica.", "body": ["As cerâmicas com padrões de corda dão nome ao período Jōmon. Objetos cotidianos e figuras de barro ajudam a estudar formas de viver anteriores às cidades que conhecemos.", "Arqueologia trabalha com vestígios e interpretações. Datas e características variam conforme região e sítio: este é um ponto de entrada, não uma origem única para todas as pessoas do arquipélago."], "sources": [{"label": "JNTO · Panorama histórico", "url": "https://www.japan.travel/en/responsible-travel-guide/features/overview-japanese-history/"}], "year": "Pré-história", "color": "clay"}, {"id": "heian", "category": "historia", "title": "Heian: a palavra ganha espaço", "kana": "平安", "tag": "794", "lead": "A corte, a escrita e outras maneiras de narrar.", "body": ["Em 794, a corte se estabeleceu em Heiankyō, na área da atual Kyoto. O período é associado a uma intensa produção cultural da aristocracia.", "Textos como O Conto de Genji, de Murasaki Shikibu, permitem entrever relações, emoções e hierarquias desse universo. A experiência da corte, porém, não resume a vida de toda a população."], "sources": [{"label": "Columbia University · Linha do tempo", "url": "https://afe.easia.columbia.edu/timelines/japan_timeline.htm"}, {"label": "The Met · O Conto de Genji", "url": "https://www.metmuseum.org/exhibitions/listings/2019/tale-of-genji/exhibition-galleries"}], "year": "794", "color": "plum", "related": ["murasaki", "kyoto"]}, {"id": "kamakura", "category": "historia", "title": "Poder militar e novos centros", "kana": "鎌倉", "tag": "FIM DO SÉCULO XII", "lead": "A história não aconteceu apenas na corte.", "body": ["A ascensão de governos militares deslocou o exercício do poder e marcou a importância política dos guerreiros. Kamakura tornou-se um desses centros.", "Samurais reais existiram em sociedades hierarquizadas e em transformação. As imagens de filmes, jogos e mangás são interpretações posteriores, que merecem ser distinguidas da pesquisa histórica."], "sources": [{"label": "Columbia University · Linha do tempo", "url": "https://afe.easia.columbia.edu/timelines/japan_timeline.htm"}], "year": "Séc. XII", "color": "ink"}, {"id": "edo", "category": "historia", "title": "Edo: a cidade vira cultura", "kana": "江戸", "tag": "1603", "lead": "Ruas, circulação de imagens e públicos urbanos.", "body": ["O governo Tokugawa teve seu centro em Edo, a atual Tóquio. A vida urbana favoreceu mercados de entretenimento e de imagens impressas.", "Gravuras ukiyo-e circularam nesse ambiente. A Grande Onda, de Hokusai, ajuda a perceber como paisagem, trabalho editorial e escolhas de composição podem construir uma imagem duradoura."], "sources": [{"label": "JNTO · Panorama histórico", "url": "https://www.japan.travel/en/responsible-travel-guide/features/overview-japanese-history/"}, {"label": "The Met · A Grande Onda", "url": "https://www.metmuseum.org/art/collection/search/45434"}], "year": "1603", "image": "great-wave", "related": ["hokusai", "tokyo"], "imageAlt": "The Great Wave at Kanagawa. Designed by Hokusai"}, {"id": "meiji", "category": "historia", "title": "Meiji: transformação e tensão", "kana": "明治", "tag": "1868", "lead": "Reformas que mudam o Estado e a vida social.", "body": ["A Restauração Meiji, em 1868, iniciou uma reorganização política e uma rápida transformação de instituições, indústrias e relações internacionais. Edo passou a se chamar Tóquio.", "Modernização não foi uma mudança simples nem igual para todos. Novas possibilidades conviveram com conflitos, desigualdades e a expansão do poder imperial."], "sources": [{"label": "JNTO · Panorama histórico", "url": "https://www.japan.travel/en/responsible-travel-guide/features/overview-japanese-history/"}, {"label": "Columbia University · Linha do tempo", "url": "https://afe.easia.columbia.edu/timelines/japan_timeline.htm"}], "year": "1868", "color": "brick"}, {"id": "guerra", "category": "historia", "title": "Guerra, perdas e memória", "kana": "記憶", "tag": "PRIMEIRA METADE DO SÉCULO XX", "lead": "Conhecer uma cultura também exige olhar para suas rupturas.", "body": ["A expansão imperial japonesa e as guerras na Ásia e no Pacífico causaram imenso sofrimento dentro e fora do país. Essa história não cabe em uma narrativa apenas de conquistas ou de progresso.", "Em agosto de 1945, Hiroshima e Nagasaki sofreram bombardeios atômicos. Preservar testemunhos, estudar responsabilidades e conhecer as experiências das vítimas são partes essenciais da memória."], "sources": [{"label": "JNTO · Panorama histórico", "url": "https://www.japan.travel/en/responsible-travel-guide/features/overview-japanese-history/"}, {"label": "Prefeitura de Hiroshima · Memória e reconstrução", "url": "https://www.pref.hiroshima.lg.jp/site/hiroshimaforpeace-en/reconstruction-index.html"}], "year": "1930–1945", "image": "hiroshima-real", "related": ["hiroshima"], "imageAlt": "The Hiroshima Peace Memorial, also known as the Atomic Bomb Dome, in Hiroshima Peace Memorial Park. The building was located near the hypocenter of the atomic bomb used on Hiroshima by US forces on August 6, 1945, and was one of the few nearby struct"}, {"id": "posguerra", "category": "historia", "title": "Reconstruir não é esquecer", "kana": "再生", "tag": "DEPOIS DE 1945", "lead": "Instituições, cidades e vidas foram refeitas.", "body": ["A reconstrução do pós-guerra envolveu profundas mudanças políticas e sociais. Uma nova Constituição foi promulgada em 1946 e entrou em vigor em 1947.", "A literatura, o cinema e os quadrinhos também exploraram perdas, trabalho e expectativas de futuro. Recomeços coexistiram com memórias difíceis."], "sources": [{"label": "Biblioteca Nacional da Dieta · Constituição", "url": "https://www.ndl.go.jp/constitution/e/outline/00outline.html"}, {"label": "Câmara dos Representantes · Constituição", "url": "https://www.shugiin.go.jp/internet/itdb_english.nsf/html/statics/english/constitution_e.htm"}], "year": "1945–1947", "related": ["tezuka", "kurosawa"]}, {"id": "ainu", "category": "historia", "title": "O Japão tem muitas vozes", "kana": "アイヌ", "tag": "DIVERSIDADE CULTURAL", "lead": "A cultura Ainu faz parte do presente, não só de um passado distante.", "body": ["Os Ainu têm língua, práticas artísticas e tradições próprias. Sua história inclui pressões de assimilação e esforços contemporâneos de revitalização cultural.", "O Upopoy, em Hokkaido, é um centro nacional de aprendizagem e promoção dessa cultura. Conhecer o Japão pede espaço para histórias que não se encaixam em uma identidade única."], "sources": [{"label": "Upopoy · Cultura Ainu", "url": "https://ainu-upopoy.go.jp/en/facility/upopoy/"}], "year": "Muitas vozes", "image": "sapporo-real", "related": ["sapporo", "naha"], "imageAlt": "\n500px provided description: Sapporo Odori Park [#city ,#night ,#cityscape ,#japan ,#building ,#sapporo ,#hokkaido]"}, {"id": "hokusai", "category": "pessoas", "title": "Katsushika Hokusai", "kana": "北斎", "tag": "ARTES VISUAIS", "lead": "Uma onda, muitas maneiras de olhar.", "body": ["Hokusai criou gravuras e livros ilustrados no Japão do período Edo. Sua obra vai muito além de uma única imagem famosa.", "Em A Grande Onda, da série Trinta e Seis Vistas do Monte Fuji, a escala da água contrasta com o pequeno perfil da montanha. Experimente encontrar o Fuji antes de voltar a olhar a onda."], "sources": [{"label": "The Met · A Grande Onda", "url": "https://www.metmuseum.org/art/collection/search/45434"}], "image": "great-wave", "field": "arte", "start": "Observe A Grande Onda: água, barcos e montanha disputam a escala.", "related": ["edo", "fuji"], "imageAlt": "The Great Wave at Kanagawa. Designed by Hokusai"}, {"id": "murasaki", "category": "pessoas", "title": "Murasaki Shikibu", "kana": "紫式部", "tag": "LITERATURA", "lead": "Uma escritora que atravessou séculos.", "body": ["Murasaki Shikibu escreveu O Conto de Genji no ambiente da corte do início do século XI. O livro é uma referência central da literatura japonesa.", "Suas relações com a pintura, os objetos e outras narrativas mostram que um texto pode continuar ganhando vidas muito depois do tempo em que foi escrito."], "sources": [{"label": "The Met · O Conto de Genji", "url": "https://resources.metmuseum.org/resources/metpublications/pdf/The_Tale_of_Genji_A_Japanese_Classic_Illuminated.pdf"}], "field": "literatura", "start": "Comece pelo contexto de Genji e suas adaptações visuais.", "related": ["heian", "kyoto"]}, {"id": "tezuka", "category": "pessoas", "title": "Osamu Tezuka", "kana": "手塚治虫", "tag": "MANGÁ & ANIMAÇÃO", "lead": "Quadrinhos como uma linguagem de possibilidades.", "body": ["Astro Boy, Fênix e outras obras fazem parte do vasto trabalho de Tezuka. Sua produção atravessou quadrinhos e animação.", "Conhecer sua trajetória é uma porta para pensar como o mangá aborda tecnologia, ética, aventura e a própria condição humana. Ele participou de um campo criativo coletivo, não de uma história feita por uma pessoa só."], "sources": [{"label": "Tezuka Osamu Official · Biografia", "url": "https://tezukaosamu.net/en/about/"}], "field": "manga", "start": "Explore Astro Boy e compare seu desenho com outras fases do autor.", "related": ["astroboy"]}, {"id": "kusama", "category": "pessoas", "title": "Yayoi Kusama", "kana": "草間彌生", "tag": "ARTE CONTEMPORÂNEA", "lead": "Repetição que transforma a percepção.", "body": ["Pontos, redes, esculturas e ambientes imersivos atravessam a obra de Kusama. Sua produção explora a repetição em diferentes materiais e escalas.", "Em vez de reduzir uma artista a um padrão reconhecível, vale acompanhar a diversidade de sua trajetória e as relações entre pintura, instalação e performance."], "sources": [{"label": "Yayoi Kusama · Biografia oficial", "url": "https://yayoi-kusama.jp/en/biography/"}], "field": "arte", "start": "Compare uma pintura de redes com uma instalação: o que muda na escala?", "color": "dots"}, {"id": "kurosawa", "category": "pessoas", "title": "Akira Kurosawa", "kana": "黒澤明", "tag": "CINEMA", "lead": "Um gesto pode mudar todo o enquadramento.", "body": ["Rashomon e Os Sete Samurais são dois caminhos para entrar no cinema de Kurosawa. Seus filmes exploram ação, dilemas e maneiras de narrar um acontecimento.", "Olhe para o movimento dentro da imagem, para os grupos de personagens e para o que cada ponto de vista permite saber. A forma também faz parte da história."], "sources": [{"label": "BFI · Por onde começar com Kurosawa", "url": "https://www.bfi.org.uk/features/where-begin-with-akira-kurosawa"}], "field": "cinema", "start": "Veja Os Sete Samurais ou leia a introdução do BFI antes da sessão.", "related": ["kamakura"]}, {"id": "sakamoto", "category": "pessoas", "title": "Ryuichi Sakamoto", "kana": "坂本龍一", "tag": "MÚSICA", "lead": "Escutar também é uma forma de descobrir.", "body": ["A trajetória de Sakamoto atravessou o Yellow Magic Orchestra, o piano, a música eletrônica e composições para cinema.", "Seu trabalho convida a escutar não apenas melodias, mas timbres, silêncios e sons do ambiente. O arquivo oficial permite acompanhar essas diferentes direções."], "sources": [{"label": "siteSakamoto · Biografia oficial", "url": "https://www.sitesakamoto.com/biography/"}], "field": "musica", "start": "Escolha uma peça de piano e outra eletrônica. Observe texturas e espaços.", "color": "sound"}, {"id": "yukawa", "category": "pessoas", "title": "Hideki Yukawa", "kana": "湯川秀樹", "tag": "CIÊNCIA", "lead": "Imaginar uma partícula antes de encontrá-la.", "body": ["Yukawa recebeu o Nobel de Física de 1949 por seu trabalho teórico sobre forças nucleares e a previsão de mésons.", "Sua história lembra que a criatividade também pertence à ciência: formular uma explicação, testá-la e revisá-la é um modo de criar conhecimento."], "sources": [{"label": "Fundação Nobel · Física de 1949", "url": "https://www.nobelprize.org/prizes/physics/1949/summary/"}], "field": "ciencia", "start": "Explore o resumo e a palestra Nobel no arquivo da premiação.", "color": "orbit"}, {"id": "tokyo", "category": "cidades", "title": "Tóquio", "kana": "東京", "tag": "KANTŌ", "lead": "O extraordinário muda a cada esquina.", "body": ["Telas e edifícios convivem com pequenas lojas, santuários, oficinas e bairros de ritmos diferentes. Um único cartão-postal não resume a metrópole.", "Observe as mudanças de escala e de uso da rua. Visitar um bairro com atenção pode revelar tanto quanto atravessar vários lugares com pressa."], "sources": [{"label": "GO TOKYO · Cultura", "url": "https://www.gotokyo.org/en/see-and-do/culture/index.html"}], "image": "tokyo-real", "region": "urbano", "related": ["edo"], "imageAlt": "Kabukichō red gate and colorful neon street signs, entertainment and red-light district at night in Kabukicho, Shinjuku, Tokyo, Japan."}, {"id": "kyoto", "category": "cidades", "title": "Kyoto", "kana": "京都", "tag": "KANSAI", "lead": "A tradição também mora no presente.", "body": ["A cultura do chá se conecta a ofícios como cerâmica, laca e trabalho com bambu. A cidade também abriga criações contemporâneas.", "Mais que procurar uma imagem de um Japão antigo, observe quem produz, cuida e dá novos usos a essas práticas."], "sources": [{"label": "Kyoto Travel · Arte e cultura", "url": "https://kyoto.travel/en/art-and-culture/"}], "image": "kyoto-real", "region": "tradicao", "related": ["heian"], "imageAlt": "View of Yasaka Pagoda, the five-storey pagoda of Hōkan-ji temple, from a street in Higashiyama near Gion."}, {"id": "osaka", "category": "cidades", "title": "Osaka", "kana": "大阪", "tag": "KANSAI", "lead": "Uma cidade que também se saboreia.", "body": ["A gastronomia, o entretenimento e a vida noturna oferecem caminhos para conhecer Osaka. Dōtonbori é um de seus cenários urbanos mais reconhecíveis.", "Olhe para além do letreiro: as mesas, o preparo e os encontros ajudam a contar a história de um lugar."], "sources": [{"label": "JNTO · Osaka", "url": "https://www.japan.travel/en/destinations/kansai/osaka/"}], "image": "osaka-real", "region": "urbano", "related": ["okonomiyaki"], "imageAlt": "Wall of signboards at Ebisu Bridge on the Dōtonbori Canal, Osaka, Japan."}, {"id": "sapporo", "category": "cidades", "title": "Sapporo", "kana": "札幌", "tag": "HOKKAIDO", "lead": "O norte tem outras escalas e histórias.", "body": ["O Parque Ōdōri participa da vida cultural de Sapporo e recebe eventos de inverno. A região também abre caminhos para conhecer a história e a cultura Ainu.", "A foto mostra o parque à noite. Para conhecer pessoas e tradições, continue pelos centros e museus dedicados à cultura local."], "sources": [{"label": "Visit Sapporo · Inverno", "url": "https://visit.sapporo.travel/seasons/winter/"}], "image": "sapporo-real", "region": "norte", "related": ["ainu", "neve"], "imageAlt": "\n500px provided description: Sapporo Odori Park [#city ,#night ,#cityscape ,#japan ,#building ,#sapporo ,#hokkaido]"}, {"id": "hiroshima", "category": "cidades", "title": "Hiroshima", "kana": "広島", "tag": "CHŪGOKU", "lead": "Memória, vida cotidiana e compromisso com a paz.", "body": ["A Cúpula da Bomba Atômica e o parque memorial guardam uma história que exige escuta e respeito. A cidade também é um espaço de vidas, trabalho e cultura contemporânea.", "Ao conhecer lugares de memória, dê tempo aos testemunhos. A história das pessoas importa mais que uma fotografia rápida."], "sources": [{"label": "Prefeitura de Hiroshima · Memória e reconstrução", "url": "https://www.pref.hiroshima.lg.jp/site/hiroshimaforpeace-en/reconstruction-index.html"}], "image": "hiroshima-real", "region": "memoria", "related": ["guerra"], "imageAlt": "The Hiroshima Peace Memorial, also known as the Atomic Bomb Dome, in Hiroshima Peace Memorial Park. The building was located near the hypocenter of the atomic bomb used on Hiroshima by US forces on August 6, 1945, and was one of the few nearby struct"}, {"id": "naha", "category": "cidades", "title": "Naha", "kana": "那覇", "tag": "OKINAWA", "lead": "Uma porta para as histórias de Ryūkyū.", "body": ["A história do antigo Reino de Ryūkyū e a cultura de Okinawa ajudam a perceber a diversidade do Japão. Naha conecta experiências urbanas e esse patrimônio insular.", "A fotografia de Shuri é de 2011, anterior ao incêndio de 2019. Trata-se de um registro de arquivo, não de uma indicação do estado atual do castelo."], "sources": [{"label": "JNTO · Naha", "url": "https://www.japan.travel/en/destinations/okinawa/Okinawa/naha-and-the-main-island/"}], "image": "naha-real", "region": "ilhas", "related": ["okinawa"], "imageAlt": "Shuri Castle in Naha, Okinawa prefecture, Japan. It was registered as part of the UNESCO World Heritage Site \"Gusuku Sites and Related Properties of the Kingdom of Ryukyu\"."}, {"id": "casa", "category": "costumes", "title": "Na entrada de uma casa", "kana": "玄関", "tag": "CASA", "lead": "Observe o limiar antes de entrar.", "body": ["Em muitas casas e em determinados estabelecimentos, espera-se que os sapatos sejam retirados. Uma mudança de nível, uma sapateira ou chinelos podem indicar o espaço adequado.", "Confira as orientações do lugar e, se houver dúvida, pergunte. Regras de uma casa ou de um templo não se aplicam automaticamente a qualquer ambiente."], "sources": [{"label": "JNTO · Costumes e convivência", "url": "https://www.japan.travel/en/guide/japanese-manners-dos-and-donts/"}], "do": "Observe os sinais e acompanhe a orientação de quem recebe.", "dont": "Evite entrar de sapatos em uma área indicada para uso sem eles."}, {"id": "trem", "category": "costumes", "title": "No transporte coletivo", "kana": "電車", "tag": "TRANSPORTE", "lead": "Compartilhar espaço também pede atenção.", "body": ["Espere as pessoas saírem antes de embarcar. Falar baixo e evitar ligações telefônicas são formas de consideração no transporte coletivo.", "Filas, assentos prioritários e orientações podem variar conforme o serviço. Observe a sinalização em vez de presumir uma única regra para todo trem."], "sources": [{"label": "JNTO · Costumes e convivência", "url": "https://www.japan.travel/en/guide/japanese-manners-dos-and-donts/"}], "do": "Deixe a passagem livre e o som dos seus aparelhos só para você.", "dont": "Evite bloquear portas ou fazer chamadas no vagão."}, {"id": "mesa", "category": "costumes", "title": "À mesa", "kana": "食事", "tag": "CONVIVÊNCIA", "lead": "Não é preciso transformar a refeição em uma prova.", "body": ["Costumes à mesa variam entre casas, tipos de restaurante e ocasiões. O mais útil é observar, perguntar com educação e respeitar a forma de servir do lugar.", "Comer macarrão fazendo algum ruído é aceito em muitos contextos. Isso não significa que um visitante tenha obrigação de imitar o gesto."], "sources": [{"label": "JNTO · Costumes e convivência", "url": "https://www.japan.travel/en/guide/japanese-manners-dos-and-donts/"}], "do": "Acompanhe as orientações do estabelecimento e aproveite a refeição.", "dont": "Evite tratar cada preferência como uma regra universal."}, {"id": "banho", "category": "costumes", "title": "Em um onsen", "kana": "温泉", "tag": "BANHOS", "lead": "Primeiro, conheça as regras do estabelecimento.", "body": ["A lavagem do corpo acontece antes da entrada no banho compartilhado. O objetivo é manter a água de imersão limpa.", "Há diferenças entre locais, inclusive sobre trajes, tatuagens e espaços privativos. Confirme diretamente as condições do estabelecimento."], "sources": [{"label": "JNTO · Cultura dos banhos", "url": "https://www.japan.travel/en/guide/how-to-best-enjoy-onsen/"}], "do": "Lave-se antes e mantenha toalhas fora da água do banho.", "dont": "Evite levar sabonete para a área de imersão."}, {"id": "fotografia", "category": "costumes", "title": "Antes de fotografar", "kana": "写真", "tag": "RESPEITO", "lead": "Uma boa imagem começa com permissão.", "body": ["Pessoas, residências e espaços religiosos merecem atenção especial. Sinalizações de proibição e orientações locais devem ser respeitadas.", "A vontade de registrar uma cena não deve atrapalhar passagens, cerimônias ou a vida de quem mora ali."], "sources": [{"label": "Kyoto Travel · Guia para visitantes responsáveis", "url": "https://kyoto.travel/en/"}], "do": "Peça permissão e respeite um não.", "dont": "Evite invadir áreas privadas ou transformar pessoas em cenário."}, {"id": "ramen", "category": "sabores", "title": "Ramen", "kana": "拉麺", "tag": "CALDO & MACARRÃO", "lead": "Uma tigela, muitos estilos.", "body": ["Ramen combina macarrão, caldo e acompanhamentos. Há estilos regionais e interpretações que mudam entre cozinhas.", "Sapporo é associada ao miso ramen, enquanto o tonkotsu tem forte relação com Kyushu. Não existe uma única tigela que represente todas as regiões."], "sources": [{"label": "JNTO · Ramen", "url": "https://www.japan.travel/en/guide/ramen/"}], "image": "ramen-real", "taste": "quente", "imageAlt": "A bowl of miso ramen topped with pork and a soft-boiled egg cut in half.  Nasushiobara, Tochigi, Japan."}, {"id": "soba", "category": "sabores", "title": "Soba & udon", "kana": "麺", "tag": "MACARRÃO", "lead": "Textura, temperatura e outra maneira de comer.", "body": ["Soba é associado ao trigo-sarraceno; udon, à farinha de trigo. Preparos e proporções podem variar.", "Ambos podem aparecer em apresentações quentes ou frias. A escolha do caldo e dos acompanhamentos muda a experiência."], "sources": [{"label": "JNTO · Comer no Japão", "url": "https://www.japan.travel/en/story/dining-out-in-japan/"}], "image": "", "taste": "macarrao"}, {"id": "okonomiyaki", "category": "sabores", "title": "Okonomiyaki", "kana": "お好み焼き", "tag": "CHAPA", "lead": "Um nome, diferenças regionais.", "body": ["Okonomiyaki reúne uma massa e ingredientes preparados na chapa. Osaka e Hiroshima são referências para conhecer versões diferentes.", "Em vez de escolher uma versão como a única autêntica, vale observar como cada região organiza ingredientes e preparo."], "sources": [{"label": "JNTO · Sabores regionais", "url": "https://www.japan.travel/en/local-specialities/local-foods/"}], "image": "", "taste": "chapa"}, {"id": "sushi", "category": "sabores", "title": "Sushi", "kana": "寿司", "tag": "ARROZ", "lead": "Olhe também para o arroz.", "body": ["Sushi envolve arroz temperado e diferentes combinações e formatos. Não é sinônimo de uma única peça de peixe cru.", "De balcões a restaurantes informais, ingredientes e modos de servir variam. Conhecer a cozinha pede atenção às diferenças, não apenas aos pratos mais fotografados."], "sources": [{"label": "JNTO · Cultura à mesa", "url": "https://www.japan.travel/en/things-to-do/eat-and-drink/"}], "image": "", "taste": "arroz"}, {"id": "washoku", "category": "sabores", "title": "Washoku", "kana": "和食", "tag": "CULTURA ALIMENTAR", "lead": "O que acontece antes e depois do prato.", "body": ["Washoku se refere a práticas, conhecimentos e tradições da cultura alimentar. A inscrição da UNESCO destaca sua relação com o Ano-Novo.", "Produzir, preparar, compartilhar e reconhecer a sazonalidade são partes dessa cultura. O patrimônio é uma prática social, não uma lista fixa de receitas."], "sources": [{"label": "UNESCO · Washoku", "url": "https://ich.unesco.org/en/RL/washoku-traditional-dietary-cultures-of-the-japanese-notably-for-the-celebration-of-the-new-year-00869"}], "image": "", "taste": "cultura"}, {"id": "cha-sabor", "category": "sabores", "title": "Chá: mais de uma xícara", "kana": "茶", "tag": "TEMPO & HOSPITALIDADE", "lead": "Um sabor pode aproximar ofícios e pessoas.", "body": ["A cultura do chá se conecta a utensílios, arquitetura, hospitalidade e diferentes maneiras de preparar e servir.", "Uma experiência de matcha e uma bebida cotidiana podem ter contextos distintos. Os dois caminhos convidam a perceber aroma, temperatura e atenção."], "sources": [{"label": "JNTO · Cerimônia do chá", "url": "https://www.japan.travel/en/guide/tea-ceremony/"}], "image": "", "taste": "cha"}, {"id": "yakushima", "category": "natureza", "title": "Yakushima: outro tempo", "kana": "森", "tag": "FLORESTA", "lead": "Musgos, raízes e uma paisagem que pede presença.", "body": ["Shiratani Unsuikyō, em Yakushima, reúne floresta, rochas e cursos de água. A observação de árvores e musgos pode mudar o ritmo de uma caminhada.", "Permaneça nas trilhas permitidas e respeite orientações de conservação. Contemplar também significa evitar que a visita apague o que veio conhecer."], "sources": [{"label": "Agência Florestal do Japão · Shiratani", "url": "https://www.rinya.maff.go.jp/e/national_forest/recreation_forest/yakushima_shiratani.html"}], "image": "forest-moss", "type": "paisagem", "related": ["mononoke", "tanabata"], "imageAlt": "Forest in Shiratani Unsui Gorge, Yakushima, Kagoshima Pref., Japan."}, {"id": "fuji", "category": "natureza", "title": "Fuji: paisagem e significado", "kana": "富士", "tag": "MONTANHA", "lead": "Uma montanha pode ser também uma história cultural.", "body": ["O reconhecimento de Fujisan pela UNESCO destaca sua dimensão sagrada e sua influência artística. A paisagem participa de peregrinações, gravuras e outras formas de memória.", "Ver o Fuji em uma imagem e visitar seus arredores são experiências diferentes. Para qualquer visita ou subida, consulte regras e condições oficiais atualizadas."], "sources": [{"label": "UNESCO · Fujisan", "url": "https://whc.unesco.org/en/list/1418/"}], "image": "great-wave", "type": "paisagem", "related": ["hokusai"], "imageAlt": "The Great Wave at Kanagawa. Designed by Hokusai"}, {"id": "okinawa", "category": "natureza", "title": "Okinawa: histórias insulares", "kana": "沖縄", "tag": "ILHAS", "lead": "O mar aproxima paisagens e culturas próprias.", "body": ["Okinawa é um arquipélago de clima subtropical e tem uma história ligada ao antigo Reino de Ryūkyū. Sua cultura não é apenas uma versão tropical de outras regiões do país.", "Litorais e recifes pedem cuidado. Patrimônio natural e cultural fazem parte de um mesmo lugar vivido por comunidades."], "sources": [{"label": "JNTO · Okinawa", "url": "https://www.japan.travel/en/destinations/okinawa/okinawa/"}], "image": "naha-real", "type": "paisagem", "related": ["naha"], "imageAlt": "Shuri Castle in Naha, Okinawa prefecture, Japan. It was registered as part of the UNESCO World Heritage Site \"Gusuku Sites and Related Properties of the Kingdom of Ryukyu\"."}, {"id": "neve", "category": "natureza", "title": "A neve muda o desenho da cidade", "kana": "雪", "tag": "INVERNO", "lead": "Sapporo encontra outras formas de ocupar a estação.", "body": ["O Festival da Neve de Sapporo apresenta esculturas e outras atividades em espaços urbanos como o Parque Ōdōri.", "É um exemplo de como a estação pode criar encontros culturais. Consulte o organizador para datas, locais e programação de cada edição."], "sources": [{"label": "Festival da Neve · Site oficial", "url": "https://www.snowfes.com/index.html"}, {"label": "Visit Sapporo · Festival da Neve", "url": "https://visit.sapporo.travel/discover/snow/sapporo-snow-festival/"}], "image": "sapporo-real", "type": "festival", "related": ["sapporo"], "imageAlt": "\n500px provided description: Sapporo Odori Park [#city ,#night ,#cityscape ,#japan ,#building ,#sapporo ,#hokkaido]"}, {"id": "tanabata", "category": "natureza", "title": "Tanabata: desejos no papel", "kana": "七夕", "tag": "FESTIVAL", "lead": "Uma história de estrelas ganha espaço nas ruas.", "body": ["A celebração se relaciona à lenda do encontro de Orihime e Hikoboshi. Escrever desejos em tiras de papel, os tanzaku, e pendurá-las em bambu é uma prática conhecida.", "Os modos e os períodos de celebração variam. Nosso pequeno papel interativo é uma homenagem criativa, sem promessa de realização de desejos."], "sources": [{"label": "Japan Society · Tanzaku", "url": "https://www.japansociety.org.uk/newsitem?pg=tanzaku"}], "type": "festival", "color": "sky"}, {"id": "gion", "category": "natureza", "title": "Gion Matsuri: a cidade se reúne", "kana": "祭", "tag": "FESTIVAL", "lead": "Um festival também é trabalho coletivo.", "body": ["Em Kyoto, o Gion Matsuri ocupa espaços urbanos e reúne desfiles de carros chamados yamaboko. A experiência envolve preparação, ofícios e participação comunitária.", "Antes de planejar uma visita, confira datas e orientações no guia oficial. Festivais são práticas vivas, não cenários disponíveis a qualquer momento."], "sources": [{"label": "JNTO · Gion Matsuri", "url": "https://www.japan.travel/en/spot/83/"}], "image": "kyoto-real", "type": "festival", "imageAlt": "View of Yasaka Pagoda, the five-storey pagoda of Hōkan-ji temple, from a street in Higashiyama near Gion."}, {"id": "momotaro", "category": "historia", "title": "Momotarō: o menino do pêssego", "kana": "桃太郎", "tag": "FOLCLORE", "lead": "Histórias viajam, mudam e voltam a ser contadas.", "body": ["Em versões conhecidas do conto, um menino nasce de um pêssego e parte em uma jornada com companheiros animais para enfrentar ogros. Okayama mantém fortes associações com essa narrativa.", "É folclore, não um relato de um acontecimento comprovado. As diferentes versões mostram como uma história pode adquirir sentidos em outros lugares e tempos."], "sources": [{"label": "Japan Search · Momotarō", "url": "https://jpsearch.go.jp/en/item/cb1-a24d9b2b_dfac_4f30_8d6d_9447643f768a"}], "year": "Folclore", "color": "peach"}, {"id": "spirited", "category": "anime", "title": "A Viagem de Chihiro", "kana": "旅", "tag": "FILME", "genre": "fantasia", "creator": "Hayao Miyazaki / Studio Ghibli", "lead": "Um filme de Hayao Miyazaki, do Studio Ghibli. Ao entrar em um mundo de espíritos, Chihiro precisa encontrar coragem e agir em um lugar cujas regras ainda não entende.", "body": ["Um filme de Hayao Miyazaki, do Studio Ghibli. Ao entrar em um mundo de espíritos, Chihiro precisa encontrar coragem e agir em um lugar cujas regras ainda não entende.", "Vale observar os pequenos trabalhos, as refeições e os momentos de silêncio: eles tornam o fantástico estranhamente familiar."], "note": "Para quem gosta de: fantasia, amadurecimento e mundos cheios de detalhes. Filme • 2001.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://gkids.com/films/spirited-away/"}], "related": []}, {"id": "onepiece", "category": "anime", "title": "One Piece", "kana": "海", "tag": "MANGÁ & ANIME", "genre": "aventura", "creator": "Eiichiro Oda", "lead": "Criado por Eiichiro Oda, acompanha Monkey D. Luffy e sua tripulação em uma viagem por mares, ilhas e sonhos imensos.", "body": ["Criado por Eiichiro Oda, acompanha Monkey D. Luffy e sua tripulação em uma viagem por mares, ilhas e sonhos imensos.", "Por trás da aventura e do humor, a história dá espaço a amizades, liberdade, injustiças e à importância de ter um lugar no mundo."], "note": "Para quem gosta de: jornadas longas, universos vastos e amizades improváveis.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/one-piece"}], "related": []}, {"id": "silent", "category": "anime", "title": "A Voz do Silêncio", "kana": "声", "tag": "MANGÁ & FILME", "genre": "drama", "creator": "Yoshitoki Ōima / Naoko Yamada", "lead": "O mangá de Yoshitoki Ōima foi adaptado para um filme dirigido por Naoko Yamada. A história aborda bullying, culpa e as dificuldades de se comunicar e reconstruir vínculos.", "body": ["O mangá de Yoshitoki Ōima foi adaptado para um filme dirigido por Naoko Yamada. A história aborda bullying, culpa e as dificuldades de se comunicar e reconstruir vínculos.", "Olhares, gestos e o próprio desenho do som participam da narrativa. É uma obra sensível que convida a olhar para o outro com mais atenção."], "note": "Temas sensíveis: bullying, sofrimento emocional e suicídio. Para quem busca um drama de reconciliação.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.elevenarts.net/titles/a-silent-voice"}], "related": []}, {"id": "fullmetal", "category": "anime", "title": "Fullmetal Alchemist", "kana": "鋼", "tag": "MANGÁ & ANIME", "genre": "aventura", "creator": "Hiromu Arakawa", "lead": "No mangá de Hiromu Arakawa, os irmãos Edward e Alphonse Elric buscam reparar as consequências de uma experiência alquímica.", "body": ["No mangá de Hiromu Arakawa, os irmãos Edward e Alphonse Elric buscam reparar as consequências de uma experiência alquímica.", "A aventura combina mistério, ação e perguntas sobre responsabilidade, poder e o valor de uma vida. Fullmetal Alchemist: Brotherhood é uma adaptação da história do mangá."], "note": "Para quem gosta de: fantasia, mistérios e dilemas morais. Contém violência e temas intensos.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/fullmetal-alchemist"}], "related": []}, {"id": "totoro", "category": "anime", "title": "Meu Amigo Totoro", "kana": "森", "tag": "FILME", "genre": "fantasia", "creator": "Hayao Miyazaki / Studio Ghibli", "lead": "No filme de Hayao Miyazaki, duas irmãs se mudam para o campo e descobrem presenças extraordinárias na paisagem.", "body": ["No filme de Hayao Miyazaki, duas irmãs se mudam para o campo e descobrem presenças extraordinárias na paisagem.", "O encanto nasce da chuva, das árvores, do vento e de um olhar infantil que encontra mistério nas coisas simples."], "note": "Para quem gosta de: natureza, infância e fantasia acolhedora. Filme • 1988.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://gkids.com/films/my-neighbor-totoro/"}], "related": []}, {"id": "march", "category": "anime", "title": "March Comes in Like a Lion", "kana": "春", "tag": "MANGÁ & ANIME", "genre": "drama", "creator": "Chica Umino", "lead": "Criada por Chica Umino, a história acompanha Rei Kiriyama, um jovem jogador profissional de shōgi que tenta encontrar equilíbrio para além do tabuleiro.", "body": ["Criada por Chica Umino, a história acompanha Rei Kiriyama, um jovem jogador profissional de shōgi que tenta encontrar equilíbrio para além do tabuleiro.", "Entre partidas e refeições compartilhadas, a obra explora solidão, afeto e a construção gradual de uma rede de apoio."], "note": "Para quem gosta de: dramas intimistas e personagens que crescem aos poucos. Aborda depressão e bullying.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://denpa.pub/book/march-comes-in-like-a-lion-volume-1"}], "related": []}, {"id": "naruto", "category": "anime", "title": "Naruto", "kana": "忍", "tag": "MANGÁ & ANIME", "genre": "aventura", "creator": "Masashi Kishimoto", "lead": "Um jovem ninja procura reconhecimento e constrói laços durante uma longa jornada.", "body": ["A aventura de Naruto mistura treinamento, rivalidades e conflitos ligados a pertencimento. O crescimento dos personagens acontece em relação a suas comunidades e escolhas."], "note": "Para quem procura: ação, amizade e uma jornada extensa. Contém violência.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://naruto-official.com/en/about"}], "related": []}, {"id": "haikyu", "category": "anime", "title": "Haikyu!!", "kana": "跳", "tag": "MANGÁ & ANIME", "genre": "esporte", "creator": "Haruichi Furudate", "lead": "Um ponto nunca pertence a uma pessoa só.", "body": ["O vôlei organiza uma história sobre esforço, técnica e colaboração. Acompanhar uma equipe também é descobrir como o talento individual encontra limites e possibilidades no grupo."], "note": "Para quem procura: esporte, competição e trabalho em equipe.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/haikyu"}], "related": []}, {"id": "spyfamily", "category": "anime", "title": "Spy × Family", "kana": "家", "tag": "MANGÁ & ANIME", "genre": "comedia", "creator": "Tatsuya Endo", "lead": "Uma família improvisada, muitos segredos.", "body": ["Um espião precisa formar uma família para sua missão. As identidades escondidas dos personagens sustentam encontros entre comédia, ação e afeto."], "note": "Para quem procura: humor, espionagem e vínculos improváveis. Contém ação e violência.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/spy-x-family"}], "related": []}, {"id": "frieren", "category": "anime", "title": "Frieren: Beyond Journey’s End", "kana": "時", "tag": "MANGÁ & ANIME", "genre": "fantasia", "creator": "Kanehito Yamada e Tsukasa Abe", "lead": "E quando a grande aventura já terminou?", "body": ["A longevidade de uma elfa muda sua relação com o tempo e com os antigos companheiros. O caminho depois da vitória se transforma em uma busca por compreender outras vidas."], "note": "Para quem procura: fantasia, memória e passagem do tempo. Contém violência.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/frieren-beyond-journeys-end"}], "related": []}, {"id": "deathnote", "category": "anime", "title": "Death Note", "kana": "影", "tag": "MANGÁ & ANIME", "genre": "suspense", "creator": "Tsugumi Ohba e Takeshi Obata", "lead": "Poder, julgamento e um jogo de perseguição.", "body": ["Um caderno sobrenatural coloca Light Yagami diante da possibilidade de matar à distância. A investigação que se segue transforma escolhas morais em um duelo de estratégias."], "note": "Para quem procura: suspense e dilemas éticos. Contém mortes, violência e temas intensos.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://www.viz.com/death-note"}], "related": []}, {"id": "astroboy", "category": "anime", "title": "Astro Boy", "kana": "鉄", "tag": "MANGÁ & ANIME", "genre": "aventura", "creator": "Osamu Tezuka", "lead": "Um menino-robô e perguntas muito humanas.", "body": ["O personagem de Tezuka abre caminhos para histórias de ciência, convivência e ética. Sua trajetória também permite observar transformações dos quadrinhos e da animação."], "note": "Para quem procura: ficção científica e um encontro com a história do mangá.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://tezukaosamu.net/en/character/25.html"}], "related": ["tezuka"]}, {"id": "mononoke", "category": "anime", "title": "Princesa Mononoke", "kana": "生", "tag": "FILME", "genre": "fantasia", "creator": "Hayao Miyazaki / Studio Ghibli", "lead": "Entre a floresta e o trabalho humano, não há respostas fáceis.", "body": ["A história reúne conflitos entre comunidades, animais e forças da floresta. Os interesses das personagens complicam uma separação simples entre heróis e vilões."], "note": "Para quem procura: fantasia e conflitos ambientais. Contém violência gráfica.", "sources": [{"label": "Obra / editora ou distribuidora oficial", "url": "https://gkids.com/films/princess-mononoke/"}], "related": ["yakushima"]}], "categories": {"historia": {"name": "Histórias", "page": "historia.html", "glyph": "時"}, "costumes": {"name": "Costumes", "page": "costumes.html", "glyph": "礼"}, "pessoas": {"name": "Pessoas", "page": "pessoas.html", "glyph": "人"}, "cidades": {"name": "Cidades", "page": "lugares.html", "glyph": "旅"}, "sabores": {"name": "Sabores", "page": "sabores.html", "glyph": "食"}, "natureza": {"name": "Natureza & festas", "page": "natureza.html", "glyph": "森"}, "anime": {"name": "Anime & mangá", "page": "anime-manga.html", "glyph": "夢"}}};